const assert = require('assert');

const BASE = 'http://127.0.0.1:18081/#/porsequencia';
const CDP = 'http://127.0.0.1:9223';

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function main() {
  const alvos = await (await fetch(CDP + '/json/list')).json();
  const alvo = alvos.find(t => t.type === 'page');
  assert(alvo, 'nenhuma aba encontrada');

  const ws = new WebSocket(alvo.webSocketDebuggerUrl);
  await new Promise((ok, falha) => {
    ws.onopen = ok;
    ws.onerror = falha;
  });

  let seq = 0;
  const pendentes = new Map();
  const excecoes = [];
  ws.onmessage = ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pendentes.has(msg.id)) {
      const { ok, falha } = pendentes.get(msg.id);
      pendentes.delete(msg.id);
      if (msg.error) falha(new Error(JSON.stringify(msg.error)));
      else ok(msg.result);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      excecoes.push(msg.params.exceptionDetails.text);
    }
  };

  function send(method, params) {
    const id = ++seq;
    return new Promise((ok, falha) => {
      pendentes.set(id, { ok, falha });
      ws.send(JSON.stringify({ id, method, params: params || {} }));
    });
  }

  async function evaluate(expressao) {
    const r = await send('Runtime.evaluate', {
      expression: expressao,
      returnByValue: true,
      awaitPromise: true
    });
    if (r.exceptionDetails) {
      throw new Error(r.exceptionDetails.text + ' ' +
        (r.exceptionDetails.exception && r.exceptionDetails.exception.description));
    }
    return r.result.value;
  }

  async function esperar(descricao, expressao, tentativas) {
    const limite = tentativas || 80;
    for (let i = 0; i < limite; i++) {
      if (await evaluate(expressao)) return;
      await sleep(250);
    }
    throw new Error('timeout esperando: ' + descricao);
  }

  const scope = "angular.element(document.querySelector('.page')).scope()";

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.navigate', { url: BASE });

  await esperar('catalogo com 7 sequencias',
    "!!document.querySelector('.sequencia-cadastro') && " +
    "document.querySelectorAll('.acordes-container').length === 7");

  const nomes = await evaluate(
    "Array.prototype.map.call(document.querySelectorAll('.acordes-container'), " +
    "function(e){ return e.getAttribute('title'); })");
  assert.deepStrictEqual(nomes.slice(0, 6), [
    'Sequência de Bm', 'Sequência de C', 'Sequência Em',
    'Sequência de C (Samba)', 'Sequência de Gm', 'Sequência de C (Samba cont.)'
  ]);
  assert.strictEqual(nomes[6], 'E2E Custom');

  // Busca pela sequência seed 1.
  await evaluate("document.querySelectorAll('.acordes-container')[1].click()");
  await esperar('resultados da sequencia 1',
    scope + ".Sequencia.musics.length === 100");
  assert.strictEqual(await evaluate(scope + ".Sequencia.minhaSequencia.id"), 1);

  // Filtro de gênero Rock pela interface (8 resultados na seed 1).
  const selecionou = await evaluate(
    "(function(){ var s=document.querySelector('select');" +
    "var o=Array.prototype.find.call(s.options, function(x){" +
    "return x.textContent.trim()==='Rock';}); if(!o) return false;" +
    "s.value=o.value; s.dispatchEvent(new Event('change',{bubbles:true}));" +
    "return true; })()");
  assert.strictEqual(selecionou, true);
  await esperar('filtro Rock na sequencia 1',
    scope + ".Sequencia.meuGenero === 'Rock' && " +
    scope + ".Sequencia.musics.length === 8");
  const soRock = await evaluate(
    scope + ".Sequencia.musics.every(function(m){ return m.genero === 'Rock'; })");
  assert.strictEqual(soRock, true);

  // Busca pela sequência customizada (C, G, Am) -> 28 músicas.
  await evaluate(
    "(function(){ var s=" + scope + "; s.Sequencia.meuGenero=''; s.$apply();" +
    "s.Sequencia.pesquisarPorSequencia(s.Sequencia.sequencias[6]); })()");
  await esperar('resultados da sequencia custom',
    scope + ".Sequencia.minhaSequencia.id === 6 && " +
    scope + ".Sequencia.musics.length === 28");

  // Cadastro pela interface.
  await evaluate(
    "(function(){ var inputs=document.querySelectorAll('.sequencia-cadastro input');" +
    "inputs[0].value='Cadastrada no browser';" +
    "inputs[0].dispatchEvent(new Event('input',{bubbles:true}));" +
    "inputs[1].value='C, G, D';" +
    "inputs[1].dispatchEvent(new Event('input',{bubbles:true}));" +
    "document.querySelector('.sequencia-cadastro button[type=submit]').click(); })()");
  await esperar('cadastro pela UI',
    "document.querySelectorAll('.acordes-container').length === 8");
  assert.strictEqual(await evaluate(
    "document.querySelectorAll('.acordes-container')[7].getAttribute('title')"),
    'Cadastrada no browser');
  const inputsLimpos = await evaluate(
    "Array.prototype.every.call(" +
    "document.querySelectorAll('.sequencia-cadastro input')," +
    "function(i){ return i.value === ''; })");
  assert.strictEqual(inputsLimpos, true);

  // Recarrega e confirma persistência do catálogo.
  await send('Page.reload');
  await esperar('catalogo com 8 apos reload',
    "!!document.querySelector('.sequencia-cadastro') && " +
    "document.querySelectorAll('.acordes-container').length === 8");

  // Erro de validação exibido na UI (400 do backend).
  await evaluate(
    "(function(){ var b=document.querySelector('.sequencia-cadastro button[type=submit]');" +
    "b.click(); })()");
  await esperar('mensagem de erro na UI',
    "!!document.querySelector('.sequencia-cadastro .text-danger') && " +
    "document.querySelector('.sequencia-cadastro .text-danger').textContent.trim().length > 0");
  const erro = await evaluate(
    "document.querySelector('.sequencia-cadastro .text-danger').textContent.trim()");
  assert(erro.length > 0, 'mensagem de erro vazia');

  assert.deepStrictEqual(excecoes, [], 'exceções JS: ' + excecoes.join('; '));

  console.log('E2E browser: OK');
  console.log('  catalogo inicial: 6 seeds + 1 custom');
  console.log('  seed 1: 100 resultados; Rock: 8');
  console.log('  custom C,G,Am: 28 resultados');
  console.log('  cadastro pela UI: 201 + reload persistiu');
  console.log('  erro 400 exibido: ' + erro);
  ws.close();
}

